param([Parameter(Mandatory=$true)][string]$OutputPath)
$ErrorActionPreference='Stop';$rules=@();$form='1600vt-v2018';$rev='2018-01-01'
function Add-R($id,$phase,$order,$condition,$fields,$message,$ref,$assessment='verified-correct',$behavior='Stops or mutates as described.',$recommend='Apply explicitly and deterministically.',$confidence='high',$questions=@()){$script:rules += [ordered]@{rule_id=$id;form_id=$form;revision=$rev;phase=$phase;order=$order;condition=$condition;fields=@($fields);accepted_behavior='Condition is false and processing continues.';rejected_behavior=$behavior;exact_message=$message;source_refs=@($ref);evidence_type=@('source');assessment=$assessment;official_behavior=$behavior;recommended_app_behavior=$recommend;confidence=$confidence;unresolved_questions=@($questions)}}
Add-R '1600vt-input-001' 'input' $null 'A negative-format money field loses focus.' @('money-fields') $null 'official-hta-runtime#negativeNumbers:L5012-L5037' 'official-bug-compatible' 'Legacy formatting permits parentheses/sign conversions and binary float rounding.' 'Use signed decimal validation and formatting.'
